struct TodayView: View {
    var body: some View {
        VStack(alignment: .leading) {
            Text("Today")
            ProgressView(value: 0.7)
            TaskRow(title: "Walk for ten minutes")
        }
        .padding()
    }
}

@State private var isExpanded = false

var body: some View {
    VStack {
        Text(isExpanded ? "Open" : "Closed")
        Button("Change state") {
            isExpanded.toggle()
        }
    }
}

@Environment(\.scenePhase) private var scenePhase

.onChange(of: scenePhase) { _, newPhase in
    if newPhase == .background {
        saveDraft()
    }
}

func progress(completed: Int, total: Int) -> Double {
    guard total > 0 else { return 0 }
    return Double(completed) / Double(total)
}

if isLoading {
    ProgressView()
} else if let errorMessage {
    ErrorView(message: errorMessage)
} else {
    ContentView()
}

struct Task: Identifiable {
    let id = UUID()
    var title: String
}

ForEach(tasks) { task in
    Text(task.title)
}

struct BreathingSession: Identifiable {
    let id: UUID
    var title: String
    var seconds: Int
    var isFavorite: Bool
}

if let photoURL = profile.photoURL {
    RemoteImage(url: photoURL)
} else {
    InitialsAvatar(name: profile.name)
}

struct ParentView: View {
    @State private var isOn = false

    var body: some View {
        SettingRow(isOn: $isOn)
    }
}

struct SettingRow: View {
    @Binding var isOn: Bool
}

do {
    state = .loading
    let items = try await service.fetchItems()
    state = items.isEmpty ? .empty : .loaded(items)
} catch {
    state = .failed(error.localizedDescription)
}

withAnimation(.spring(duration: 0.5, bounce: 0.18)) {
    isExpanded.toggle()
}

struct ExpandableCard: View {
    @State private var isExpanded = false

    var body: some View {
        VStack(alignment: .leading) {
            Text("Details")
            if isExpanded {
                Text("The longer explanation appears here.")
            }
        }
        .frame(height: isExpanded ? 180 : 80)
        .onTapGesture {
            withAnimation(.spring(duration: 0.5, bounce: 0.15)) {
                isExpanded.toggle()
            }
        }
    }
}

Button("Expand") {
    withAnimation(.easeOut(duration: 0.25)) {
        isExpanded.toggle()
    }
}

Card()
    .scaleEffect(isFavorite ? 1.04 : 1)
    .animation(.spring, value: isFavorite)

if isVisible {
    NotificationBanner()
        .transition(
            .asymmetric(
                insertion: .move(edge: .top).combined(with: .opacity),
                removal: .opacity
            )
        )
}

@Namespace private var motion

if isDetail {
    DetailCard()
        .matchedGeometryEffect(id: "card", in: motion)
} else {
    CompactCard()
        .matchedGeometryEffect(id: "card", in: motion)
}

enum FeedbackPhase: CaseIterable {
    case rest, focus, confirmed
}

PhaseAnimator(FeedbackPhase.allCases, trigger: confirmationCount) {
    content, phase in
    content
        .scaleEffect(phase == .focus ? 1.08 : 1)
        .opacity(phase == .rest ? 0.7 : 1)
} animation: { phase in
    phase == .confirmed ? .spring(duration: 0.35) : .easeOut
}

struct Values {
    var scale = 1.0
    var y = 0.0
}

content.keyframeAnimator(initialValue: Values(), trigger: count) {
    view, value in
    view.scaleEffect(value.scale).offset(y: value.y)
} keyframes: { _ in
    KeyframeTrack(\.scale) {
        SpringKeyframe(1.15, duration: 0.22)
        CubicKeyframe(1.0, duration: 0.18)
    }
    KeyframeTrack(\.y) {
        CubicKeyframe(-12, duration: 0.18)
        CubicKeyframe(0, duration: 0.22)
    }
}

@GestureState private var dragX: CGFloat = 0
@State private var page = 0

DragGesture()
    .updating($dragX) { value, state, _ in
        state = value.translation.width
    }
    .onEnded { value in
        let shouldAdvance = value.predictedEndTranslation.width < -120
        withAnimation(.spring(duration: 0.45, bounce: 0.12)) {
            if shouldAdvance { page += 1 }
        }
    }

enum MotionTokens {
    static let feedbackQuick = Animation.easeOut(duration: 0.18)
    static let transitionStandard = Animation.spring(duration: 0.45, bounce: 0.12)
    static let celebration = Animation.spring(duration: 0.7, bounce: 0.28)
}

@Environment(\.accessibilityReduceMotion) private var reduceMotion

withAnimation(reduceMotion ? .easeOut(duration: 0.15) : .spring) {
    isPresented = true
}

DetailView()
    .transition(reduceMotion ? .opacity : .scale.combined(with: .opacity))

.reveal {
  opacity: 0;
  transform: translateY(16px);
  transition: opacity 300ms ease-out, transform 300ms ease-out;
}

.reveal.is-visible {
  opacity: 1;
  transform: translateY(0);
}

@media (prefers-reduced-motion: reduce) {
  .reveal { transform: none; transition-duration: 1ms; }
}

const animation = card.animate(
  [
    { opacity: 0, transform: "translateY(16px)" },
    { opacity: 1, transform: "translateY(0)" }
  ],
  { duration: 320, easing: "cubic-bezier(.2,.8,.2,1)", fill: "both" }
);

pauseButton.onclick = () => animation.pause();

const observer = new IntersectionObserver(entries => {
  for (const entry of entries) {
    if (entry.isIntersecting) {
      entry.target.classList.add("is-visible");
      observer.unobserve(entry.target);
    }
  }
}, { threshold: 0.25 });

document.querySelectorAll(".reveal").forEach(el => observer.observe(el));

@keyframes grow-progress {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}

.progress-bar {
  transform-origin: left;
  animation: grow-progress linear;
  animation-timeline: scroll(root block);
}

import { motion, useReducedMotion } from "motion/react";

function Reveal({ children }) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      initial={{ opacity: 0, y: reduce ? 0 : 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.3 }}
    >
      {children}
    </motion.div>
  );
}

gsap.registerPlugin(ScrollTrigger);

const timeline = gsap.timeline({
  scrollTrigger: {
    trigger: ".story",
    start: "top top",
    end: "+=1800",
    scrub: true,
    pin: true,
    markers: true
  }
});

timeline
  .from(".chapter-one", { opacity: 0, y: 40 })
  .to(".chapter-one", { opacity: 0 })
  .from(".chapter-two", { opacity: 0, y: 40 });
